import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void mse_forward_kernel(
    const half* predictions,
    const half* targets,
    half* output,
    int64_t total_elements
) {
    // Shared memory for reduction
    extern __shared__ half sdata[];

    int tid = threadIdx.x;
    int bid = blockIdx.x;
    int block_size = blockDim.x;

    // Each thread processes multiple elements
    half sum = __hzero();
    int64_t offset = bid * block_size + tid;

    // Process elements with grid-stride loop
    for (int64_t i = offset; i < total_elements; i += block_size * gridDim.x) {
        half diff = __hsub(predictions[i], targets[i]);
        half squared = __hmul(diff, diff);
        sum = __hadd(sum, squared);
    }

    sdata[tid] = sum;
    __syncthreads();

    // Reduction in shared memory
    for (int s = block_size / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] = __hadd(sdata[tid], sdata[tid + s]);
        }
        __syncthreads();
    }

    // Write result for this block to global memory
    if (tid == 0) {
        atomicAdd(output, sdata[0]);
    }
}

__global__ void mse_backward_kernel(
    const half* predictions,
    const half* targets,
    half* grad_predictions,
    half* grad_targets,
    int64_t total_elements
) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        half diff = __hsub(predictions[idx], targets[idx]);
        half grad_val = __hmul(__float2half(2.0f), diff);

        if (grad_predictions != nullptr) {
            grad_predictions[idx] = grad_val;
        }
        if (grad_targets != nullptr) {
            grad_targets[idx] = __hneg(grad_val);
        }
    }
}
"""

# Python wrapper
def compile_and_run():
    # Load the CUDA extension
    module = load_inline(
        name="mse_cuda",
        cpp_sources="",
        cuda_sources=cuda_source,
        functions=["mse_forward_kernel", "mse_backward_kernel"],
        verbose=True
    )

    class ModelNew(torch.nn.Module):
        def __init__(self):
            super(ModelNew, self).__init__()

        def forward(self, predictions, targets):
            # Validate input shapes
            assert predictions.shape == targets.shape, "Predictions and targets must have the same shape"

            # Flatten tensors for processing
            flat_pred = predictions.view(-1)
            flat_target = targets.view(-1)

            # Get total number of elements
            total_elements = flat_pred.numel()

            # Allocate output tensor
            output = torch.zeros(1, dtype=torch.float32, device=predictions.device)

            # Configure kernel launch parameters
            block_size = 256
            grid_size = min(65535, (total_elements + block_size - 1) // block_size)

            # Launch kernel
            shared_mem_size = block_size * sizeof(half)
            module.mse_forward_kernel[
                grid_size, block_size, shared_mem_size
            ](
                flat_pred.data_ptr(),
                flat_target.data_ptr(),
                output.data_ptr(),
                total_elements
            )

            # Normalize by total elements
            result = output / static_cast<float>(total_elements)
            return result

        def backward(self, predictions, targets):
            # This would be used for gradient computation in a more complex scenario
